using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Xml;

namespace SaovietTax.DTO
{
    public class SvgCaptchaSolver2
    {
        private string model = "";

        // Hàm này giờ CHỈ nhận chuỗi văn bản XML (đã giải mã từ Base64)
        public string SolveCaptcha(string svgXml)
        {
            byte[] modelBytes = Convert.FromBase64String(model);
            string modelJson = Encoding.UTF8.GetString(modelBytes);
            var parsedModel = JsonSerializer.Deserialize<Dictionary<string, string>>(modelJson);

            XmlDocument doc = new XmlDocument();
            doc.LoadXml(svgXml); // Nạp chuỗi XML trực tiếp
            var paths = doc.GetElementsByTagName("path");

            List<XmlElement> noStrokePaths = new List<XmlElement>();
            foreach (XmlElement path in paths)
            {
                if (!path.HasAttribute("stroke") || string.IsNullOrEmpty(path.GetAttribute("stroke")))
                {
                    noStrokePaths.Add(path);
                }
            }

            if (noStrokePaths.Count == 0) return "";

            List<int> vals = new List<int>();
            foreach (var path in noStrokePaths)
            {
                string d = path.GetAttribute("d");

                // Lấy tọa độ X chính xác sau chữ M
                var match = Regex.Match(d, @"M\s*([-\d.]+)");

                if (match.Success && double.TryParse(match.Groups[1].Value,
                    System.Globalization.NumberStyles.Any,
                    System.Globalization.CultureInfo.InvariantCulture,
                    out double val))
                {
                    vals.Add((int)Math.Round(val));
                }
                else
                {
                    vals.Add(0);
                }
            }

            var indexedVals = vals
                .Select((v, i) => new { Val = v, OriginalIndex = i })
                .OrderBy(x => x.Val)
                .ToList();

            string[] solution = new string[noStrokePaths.Count];

            for (int i = 0; i < noStrokePaths.Count; i++)
            {
                // CHỈ giữ lại các chữ cái (M, L, Q, C, Z...) để so khớp chính xác với Dictionary
                string pattern = Regex.Replace(noStrokePaths[i].GetAttribute("d"), @"[^A-Za-z]", "");

                int sortedIndex = indexedVals.FindIndex(x => x.OriginalIndex == i);

                if (sortedIndex >= 0 && sortedIndex < solution.Length && parsedModel.ContainsKey(pattern))
                {
                    solution[sortedIndex] = parsedModel[pattern];
                }
            }

            return string.Join("", solution);
        }
    }
}